const LINE = 64;
const STRUCT_BYTES = 48;
const structsPerLine = Math.floor(LINE / STRUCT_BYTES);
const wasted = LINE - structsPerLine * STRUCT_BYTES;
const counter = 8;
const padding = LINE - counter;
console.log('structs per line:', structsPerLine);
console.log('wasted bytes per line:', wasted);
console.log('pad an 8B counter with', padding, 'bytes -> 64B total');
